from dataclasses import dataclass
from datetime import datetime
from enum import Enum
from typing import Optional


class Status(Enum):
    COMPLETED = "completed"
    NEEDS_CONFIRMATION = "needs_confirmation"


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


@dataclass(frozen=True)
class CheckoutResult:
    status: Status
    total_cents: int
    promotion_applied: bool
    message: Optional[str] = None


# PROVISIONAL policy (product undecided): an expired promotion never applies;
# the customer must confirm paying the undiscounted total before the order completes.
def checkout(subtotal_cents: int, promotion: Optional[Promotion], now: datetime,
             confirmed_full_price: bool = False) -> CheckoutResult:
    if promotion is None:
        return CheckoutResult(Status.COMPLETED, subtotal_cents, False)
    if now <= promotion.expires_at:
        total = subtotal_cents * (100 - promotion.percent_off) // 100
        return CheckoutResult(Status.COMPLETED, total, True)
    if confirmed_full_price:
        return CheckoutResult(Status.COMPLETED, subtotal_cents, False)
    return CheckoutResult(
        Status.NEEDS_CONFIRMATION, subtotal_cents, False,
        f"Promotion {promotion.code} has expired; confirm to pay full price.")
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
from checkout import checkout, Promotion, Status

NOW = datetime(2026, 11, 22, 12)
def promo(delta): return Promotion("SAVE10", 10, NOW + delta)

def test_valid_promotion_applies():
    r = checkout(1000, promo(timedelta(days=1)), NOW)
    assert (r.status, r.total_cents, r.promotion_applied) == (Status.COMPLETED, 900, True)

def test_no_promotion():
    assert checkout(1000, None, NOW).total_cents == 1000

def test_expired_requires_confirmation_and_is_not_discounted():
    r = checkout(1000, promo(-timedelta(seconds=1)), NOW)
    assert r.status == Status.NEEDS_CONFIRMATION
    assert r.total_cents == 1000 and not r.promotion_applied
    assert "SAVE10" in r.message

def test_expired_confirmed_completes_at_full_price():
    r = checkout(1000, promo(-timedelta(days=1)), NOW, confirmed_full_price=True)
    assert (r.status, r.total_cents, r.promotion_applied) == (Status.COMPLETED, 1000, False)

def test_expiry_boundary_is_still_valid():
    assert checkout(1000, promo(timedelta(0)), NOW).promotion_applied
E
